PRAGMA foreign_keys = ON;
CREATE TABLE organizations (id TEXT PRIMARY KEY, name TEXT NOT NULL, slug TEXT NOT NULL UNIQUE, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE users (id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE, name TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'ACTIVE', created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE memberships (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), user_id TEXT NOT NULL REFERENCES users(id), role TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'ACTIVE', client_id TEXT REFERENCES clients(id), created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, UNIQUE(organization_id,user_id));
CREATE INDEX idx_memberships_org ON memberships(organization_id,created_at);
CREATE TABLE roles (id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE, description TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE permissions (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), role_id TEXT REFERENCES roles(id), resource TEXT NOT NULL, action TEXT NOT NULL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE INDEX idx_permissions_org ON permissions(organization_id,created_at);
CREATE TABLE invitations (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), email TEXT NOT NULL, role TEXT NOT NULL, client_id TEXT REFERENCES clients(id), token_hash TEXT NOT NULL UNIQUE, expires_at INTEGER NOT NULL, used_at INTEGER, created_by TEXT REFERENCES users(id), created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE INDEX idx_invitations_org ON invitations(organization_id,created_at);
CREATE TABLE sessions (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), user_id TEXT REFERENCES users(id), token_hash TEXT UNIQUE, expires_at INTEGER, revoked_at INTEGER, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE INDEX idx_sessions_org ON sessions(organization_id,created_at);
CREATE TABLE activities (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), name TEXT, kind TEXT, due_date TEXT, description TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE INDEX idx_activities_org ON activities(organization_id,created_at);
CREATE TABLE notes (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), resource_type TEXT NOT NULL, resource_id TEXT NOT NULL, content TEXT NOT NULL, created_by TEXT REFERENCES users(id), created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE INDEX idx_notes_org ON notes(organization_id,created_at);
CREATE TABLE opportunities (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), name TEXT NOT NULL, contact_id TEXT REFERENCES contacts(id), owner_id TEXT REFERENCES users(id), status TEXT DEFAULT 'NEW', next_action TEXT NOT NULL, value_cents INTEGER DEFAULT 0, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE INDEX idx_opportunities_org ON opportunities(organization_id,created_at);
CREATE TABLE milestones (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), name TEXT NOT NULL, project_id TEXT NOT NULL REFERENCES projects(id), status TEXT DEFAULT 'PENDING', due_date TEXT, position INTEGER DEFAULT 0, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE INDEX idx_milestones_org ON milestones(organization_id,created_at);
CREATE TABLE deliverables (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), name TEXT NOT NULL, project_id TEXT NOT NULL REFERENCES projects(id), status TEXT DEFAULT 'DRAFT', version INTEGER DEFAULT 1, body TEXT, client_visible INTEGER DEFAULT 0, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE INDEX idx_deliverables_org ON deliverables(organization_id,created_at);
CREATE TABLE quote_items (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), quote_id TEXT NOT NULL REFERENCES quotes(id), name TEXT NOT NULL, quantity REAL NOT NULL DEFAULT 1, unit_price_cents INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE INDEX idx_quote_items_org ON quote_items(organization_id,created_at);
CREATE TABLE payments (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), invoice_id TEXT REFERENCES invoices(id), amount_cents INTEGER NOT NULL CHECK(amount_cents>=0), external_reference TEXT, paid_at INTEGER, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE INDEX idx_payments_org ON payments(organization_id,created_at);
CREATE TABLE agent_definitions (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), name TEXT NOT NULL, specialization TEXT NOT NULL, model TEXT, provider TEXT, scope TEXT NOT NULL, prompt_version TEXT NOT NULL DEFAULT '1.0', tools TEXT NOT NULL DEFAULT '[]', max_tokens INTEGER NOT NULL DEFAULT 1800, timeout_ms INTEGER DEFAULT 25000, approval_level TEXT DEFAULT 'HUMAN_REQUIRED', status TEXT DEFAULT 'UNCONFIGURED', created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE INDEX idx_agent_definitions_org ON agent_definitions(organization_id,created_at);
CREATE TABLE agent_steps (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), run_id TEXT NOT NULL REFERENCES agent_runs(id), name TEXT NOT NULL, status TEXT NOT NULL, output TEXT, duration_ms INTEGER, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE INDEX idx_agent_steps_org ON agent_steps(organization_id,created_at);
CREATE TABLE agent_artifacts (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), run_id TEXT NOT NULL REFERENCES agent_runs(id), name TEXT NOT NULL, kind TEXT NOT NULL, content TEXT, r2_key TEXT, version INTEGER DEFAULT 1, sha256 TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE INDEX idx_agent_artifacts_org ON agent_artifacts(organization_id,created_at);
CREATE TABLE agent_budgets (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), period_start INTEGER NOT NULL, period_end INTEGER NOT NULL, limit_cents INTEGER NOT NULL DEFAULT 0 CHECK(limit_cents>=0), used_cents INTEGER NOT NULL DEFAULT 0 CHECK(used_cents>=0), reserved_cents INTEGER NOT NULL DEFAULT 0 CHECK(reserved_cents>=0), created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, UNIQUE(organization_id,period_start));
CREATE INDEX idx_agent_budgets_org ON agent_budgets(organization_id,created_at);
CREATE TABLE agent_tools (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), name TEXT NOT NULL, scope TEXT NOT NULL, approval_required INTEGER NOT NULL DEFAULT 1, enabled INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE INDEX idx_agent_tools_org ON agent_tools(organization_id,created_at);
CREATE TABLE model_providers (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), name TEXT NOT NULL, provider TEXT NOT NULL, model TEXT NOT NULL, status TEXT DEFAULT 'DISABLED', input_cents_per_million INTEGER DEFAULT 0, output_cents_per_million INTEGER DEFAULT 0, priority INTEGER DEFAULT 100, failure_count INTEGER DEFAULT 0, circuit_open_until INTEGER, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE INDEX idx_model_providers_org ON model_providers(organization_id,created_at);
CREATE TABLE workflow_definitions (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), name TEXT NOT NULL, event_type TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, status TEXT DEFAULT 'DRAFT', steps TEXT NOT NULL DEFAULT '[]', created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE INDEX idx_workflow_definitions_org ON workflow_definitions(organization_id,created_at);
CREATE TABLE workflow_events (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), execution_id TEXT REFERENCES workflow_executions(id), event_type TEXT NOT NULL, idempotency_key TEXT UNIQUE, payload TEXT, status TEXT NOT NULL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE INDEX idx_workflow_events_org ON workflow_events(organization_id,created_at);
CREATE TABLE audit_logs (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), user_id TEXT REFERENCES users(id), action TEXT NOT NULL, resource_type TEXT NOT NULL, resource_id TEXT, details TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE INDEX idx_audit_logs_org ON audit_logs(organization_id,created_at);
CREATE TABLE settings (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), name TEXT NOT NULL, value TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, UNIQUE(organization_id,name));
CREATE INDEX idx_settings_org ON settings(organization_id,created_at);
CREATE TABLE feature_flags (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), name TEXT NOT NULL, enabled INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, UNIQUE(organization_id,name));
CREATE INDEX idx_feature_flags_org ON feature_flags(organization_id,created_at);
CREATE TABLE notifications (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), name TEXT, body TEXT, status TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE INDEX idx_notifications_org ON notifications(organization_id,created_at);
CREATE TABLE content_revisions (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), entry_id TEXT NOT NULL REFERENCES content_entries(id), author_id TEXT REFERENCES users(id), name TEXT NOT NULL, body TEXT, version INTEGER NOT NULL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE INDEX idx_content_revisions_org ON content_revisions(organization_id,created_at);
CREATE TABLE intake_keys (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), request_key TEXT NOT NULL, lead_id TEXT REFERENCES leads(id), expires_at INTEGER NOT NULL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, UNIQUE(organization_id,request_key));
CREATE INDEX idx_intake_keys_org ON intake_keys(organization_id,created_at);
CREATE TABLE rate_limits (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), bucket_key TEXT NOT NULL, count INTEGER NOT NULL DEFAULT 0, expires_at INTEGER NOT NULL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, UNIQUE(organization_id,bucket_key));
CREATE INDEX idx_rate_limits_org ON rate_limits(organization_id,created_at);
CREATE TABLE analytics_events (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), name TEXT NOT NULL, path TEXT, source TEXT, occurred_at INTEGER NOT NULL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE INDEX idx_analytics_events_org ON analytics_events(organization_id,created_at);
CREATE TABLE attachments (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), name TEXT NOT NULL, resource_type TEXT NOT NULL, resource_id TEXT NOT NULL, media_id TEXT NOT NULL REFERENCES media_assets(id), created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE INDEX idx_attachments_org ON attachments(organization_id,created_at);
CREATE TABLE interactions (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), contact_id TEXT REFERENCES contacts(id), channel TEXT NOT NULL, direction TEXT NOT NULL, body TEXT NOT NULL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE INDEX idx_interactions_org ON interactions(organization_id,created_at);
CREATE TABLE issues (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), project_id TEXT REFERENCES projects(id), name TEXT NOT NULL, description TEXT, status TEXT DEFAULT 'OPEN', created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE INDEX idx_issues_org ON issues(organization_id,created_at);
CREATE TABLE releases (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), project_id TEXT REFERENCES projects(id), name TEXT NOT NULL, version TEXT NOT NULL, status TEXT DEFAULT 'DRAFT', evidence TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE INDEX idx_releases_org ON releases(organization_id,created_at);
CREATE TABLE contacts (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), name TEXT, email TEXT, phone TEXT, company_id TEXT REFERENCES companies(id), notes TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE INDEX idx_contacts_org ON contacts(organization_id,created_at);
CREATE TABLE companies (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), name TEXT, website TEXT, industry TEXT, notes TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE INDEX idx_companies_org ON companies(organization_id,created_at);
CREATE TABLE leads (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), name TEXT, contact_id TEXT REFERENCES contacts(id), message TEXT, source TEXT, estimated_value_cents INTEGER, next_action TEXT, owner_id TEXT REFERENCES users(id), status TEXT NOT NULL DEFAULT 'NEW', classification TEXT, brief TEXT, budget_text TEXT, urgency TEXT, language TEXT DEFAULT 'it', created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE INDEX idx_leads_org ON leads(organization_id,created_at);
CREATE TABLE deals (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), name TEXT, lead_id TEXT REFERENCES leads(id), value_cents INTEGER, probability INTEGER, next_action TEXT, owner_id TEXT REFERENCES users(id), due_date TEXT, status TEXT NOT NULL DEFAULT 'QUALIFICATION', created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE INDEX idx_deals_org ON deals(organization_id,created_at);
CREATE TABLE clients (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), name TEXT, contact_id TEXT REFERENCES contacts(id), company_id TEXT REFERENCES companies(id), status TEXT NOT NULL DEFAULT 'ACTIVE', created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE INDEX idx_clients_org ON clients(organization_id,created_at);
CREATE TABLE projects (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), name TEXT, client_id TEXT REFERENCES clients(id), description TEXT, due_date TEXT, budget_cents INTEGER, owner_id TEXT REFERENCES users(id), status TEXT NOT NULL DEFAULT 'PLANNING', visibility TEXT NOT NULL DEFAULT 'TEAM', created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE INDEX idx_projects_org ON projects(organization_id,created_at);
CREATE TABLE tasks (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), name TEXT, project_id TEXT REFERENCES projects(id), priority TEXT, description TEXT, assignee_id TEXT REFERENCES users(id), due_date TEXT, status TEXT NOT NULL DEFAULT 'TODO', created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE INDEX idx_tasks_org ON tasks(organization_id,created_at);
CREATE TABLE quotes (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), name TEXT, client_id TEXT REFERENCES clients(id), project_id TEXT REFERENCES projects(id), summary TEXT, scope TEXT, exclusions TEXT, assumptions TEXT, timeline TEXT, terms TEXT, amount_cents INTEGER, valid_until TEXT, status TEXT NOT NULL DEFAULT 'DRAFT', created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE INDEX idx_quotes_org ON quotes(organization_id,created_at);
CREATE TABLE contracts (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), name TEXT, client_id TEXT REFERENCES clients(id), project_id TEXT REFERENCES projects(id), body TEXT, due_date TEXT, status TEXT NOT NULL DEFAULT 'DRAFT', created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE INDEX idx_contracts_org ON contracts(organization_id,created_at);
CREATE TABLE invoices (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), name TEXT, client_id TEXT REFERENCES clients(id), project_id TEXT REFERENCES projects(id), amount_cents INTEGER, due_date TEXT, external_reference TEXT, status TEXT NOT NULL DEFAULT 'DRAFT', created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE INDEX idx_invoices_org ON invoices(organization_id,created_at);
CREATE TABLE expenses (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), name TEXT, project_id TEXT REFERENCES projects(id), amount_cents INTEGER, category TEXT, due_date TEXT, status TEXT NOT NULL DEFAULT 'PLANNED', created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE INDEX idx_expenses_org ON expenses(organization_id,created_at);
CREATE TABLE services (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), name TEXT, slug TEXT, category TEXT, description TEXT, status TEXT NOT NULL DEFAULT 'DRAFT', created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE INDEX idx_services_org ON services(organization_id,created_at);
CREATE TABLE portfolio_items (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), name TEXT, slug TEXT, kind TEXT, description TEXT, status TEXT NOT NULL DEFAULT 'DRAFT', created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE INDEX idx_portfolio_items_org ON portfolio_items(organization_id,created_at);
CREATE TABLE content_entries (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), name TEXT, slug TEXT, category TEXT, body TEXT, meta_description TEXT, status TEXT NOT NULL DEFAULT 'DRAFT', created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE INDEX idx_content_entries_org ON content_entries(organization_id,created_at);
CREATE TABLE approvals (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), name TEXT, reason TEXT, risk TEXT, cost_cents INTEGER, status TEXT NOT NULL DEFAULT 'PENDING', resource_type TEXT NOT NULL, resource_id TEXT NOT NULL, evidence TEXT, requested_by TEXT REFERENCES users(id), decided_by TEXT REFERENCES users(id), decided_at INTEGER, version INTEGER NOT NULL DEFAULT 1, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE INDEX idx_approvals_org ON approvals(organization_id,created_at);
CREATE TABLE agent_runs (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), name TEXT, agent_id TEXT REFERENCES agent_definitions(id), error TEXT, status TEXT NOT NULL DEFAULT 'QUEUED', input TEXT NOT NULL, output TEXT, cost_cents INTEGER NOT NULL DEFAULT 0, reserved_cents INTEGER NOT NULL DEFAULT 0, provider TEXT, model TEXT, tokens_used INTEGER DEFAULT 0, completed_at INTEGER, requested_by TEXT REFERENCES users(id), created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE INDEX idx_agent_runs_org ON agent_runs(organization_id,created_at);
CREATE TABLE workflow_executions (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), name TEXT, event_type TEXT, status TEXT, lead_id TEXT REFERENCES leads(id), version INTEGER NOT NULL DEFAULT 1, current_step TEXT, error TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE INDEX idx_workflow_executions_org ON workflow_executions(organization_id,created_at);
CREATE TABLE media_assets (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), name TEXT, mime_type TEXT, size_bytes INTEGER, status TEXT, client_id TEXT REFERENCES clients(id), r2_key TEXT NOT NULL, uploaded_by TEXT REFERENCES users(id), sha256 TEXT, scan_result TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE INDEX idx_media_assets_org ON media_assets(organization_id,created_at);
CREATE TABLE task_dependencies (task_id TEXT NOT NULL REFERENCES tasks(id), depends_on_task_id TEXT NOT NULL REFERENCES tasks(id), PRIMARY KEY(task_id,depends_on_task_id), CHECK(task_id<>depends_on_task_id));
CREATE TABLE task_assignments (task_id TEXT NOT NULL REFERENCES tasks(id), user_id TEXT NOT NULL REFERENCES users(id), PRIMARY KEY(task_id,user_id));
CREATE UNIQUE INDEX contacts_org_email ON contacts(organization_id,lower(email));
